"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15055"],{4959(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.casas_arredondamento_indevido","status":422,"titulo":"Casas de arredondamento n\xe3o se aplicam quando a classifica\xe7\xe3o \xe9 importada"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.casas_arredondamento_indevido","requisitos":[],"oQueAconteceu":["A regra de c\xe1lculo declarada \xe9 `CLASSIFICACAO_IMPORTADA`, mas a configura\xe7\xe3o\\ntamb\xe9m informou `casasArredondamento`. \xc9 a metade do mesmo par de campos que\\n[`arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_indevido)\\ncobre para `regraArredondamentoCodigo` \u2014 as confer\xeancias s\xe3o separadas\\npropositalmente, cada uma atribu\xedda ao campo que ela reprova, para que a\\nresposta n\xe3o aponte um campo pelo erro do outro quando s\xf3 um dos dois vier\\npreenchido.","No caminho de defini\xe7\xe3o, pode aparecer ao lado de `arredondamento_indevido`\\n(quando os dois campos v\xeam preenchidos), de\\n[`eliminacao_indevida`](/erros/uniplus.selecao.configuracao_classificacao.eliminacao_indevida)\\ne de\\n[`eliminacao_enem_fora_de_processo_enem`](/erros/uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem)\\nna mesma resposta (acumula, ADR-0125). Nunca coexiste com\\n[`arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_obrigatorio)\\nnem com\\n[`casas_arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_obrigatorio)\\n\u2014 pertencem ao ramo oposto (c\xe1lculo local)."],"comoResolver":["Remova `casasArredondamento` da configura\xe7\xe3o quando `regraCalculoCodigo` for\\n`CLASSIFICACAO_IMPORTADA`. Se a inten\xe7\xe3o era arredondar localmente, declare\\n`FORMULA_MEDIA_PONDERADA` como regra de c\xe1lculo."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);